        OC = self.conv2d.out_channels
        KH = self.kernel_size
        KW = self.kernel_size
        stride = self.stride
        padding = self.padding
        dilation = self.dilation
        block = (32, 8, 1)
        tile_w = (block[0] - 1) * stride + (KW - 1) * dilation + 1
        tile_h = (block[1] - 1) * stride + (KH - 1) * dilation + 1
        shared_mem_bytes = IC * KH * KW * 4 * 2 + tile_h * tile_w * 4

